+pub fn test_vdso_all_cpus_mapped() -> Result<(), &'static str> {
+    for cpu_id in 0..MAX_CPUS {
+        let vdso_ptr = crate::vdso::vdso_page_for_cpu(cpu_id);
+        if vdso_ptr.is_null() {
+            return Err("vDSO page not initialized for CPU");
+        }
