+        let end = {
+            let (lo, hi) = {
+                let lo: u32;
+                let hi: u32;
+                unsafe { core::arch::asm!("rdtsc", out("eax") lo, out("edx") hi) };
+                (lo, hi)
+            };
+            ((hi as u64) << 32) | (lo as u64)
+        };
+
+        let elapsed = end.wrapping_sub(start);
+        // Convert cycles to ns using calibrated TSC conversion
