+    // Read current PID via vDSO
+    let mut seq = vdso.pid_cpu_seq.load(Ordering::Acquire);
+    let parent_pid = loop {
+        let pid = vdso.pid.load(Ordering::Relaxed);
+        let seq2 = vdso.pid_cpu_seq.load(Ordering::Acquire);
+        if seq == seq2 && seq % 2 == 0 {
+            break pid;
+        }
+        seq = seq2;
+    };
