+    }
+
+    // Verify cpu_id matches current CPU (Acquire synchronizes with init's Release store)
+    let cpu_id = vdso.cpu_id.load(Ordering::Acquire);
+    if cpu_id != crate::smp::get_cpu_id() as u32 {
+        return Err("vDSO cpu_id mismatch");
+    }
+
+    Ok(())
