+        let Some(&phys_offset) = crate::memory::PHYSICAL_MEMORY_OFFSET.get() else {
+            crate::serial_write("HHDM offset not set\n");
+            x86_64::instructions::interrupts::disable();
+            loop {
+                x86_64::instructions::hlt();
