+/// Kernel feature flags for CLOCK_SKYIOUS_KERNEL_FLAGS (103).
+/// Bitfield exposed via vDSO for userspace feature detection.
+pub mod kernel_flags {
+    pub const HAS_AVX2: u64 = 1 << 0; // CPUID leaf 7 EBX bit 5
+    #[allow(dead_code)] // Used by userspace via vDSO
+    pub const HAS_NVME: u64 = 1 << 1; // NVMe controller present
+    #[allow(dead_code)] // Used by userspace via vDSO
+    pub const HAS_XHCI: u64 = 1 << 2; // xHCI USB controller present
+    #[allow(dead_code)] // Used by userspace via vDSO
+    pub const HAS_VIRTIO_GPU: u64 = 1 << 3; // VirtIO GPU present
+                                            // Bits 4-15 reserved for net stack version and FS features
+}
+
+/// vDSO data structure ΓÇö exactly one page (4096 bytes), cache-line aligned.
+///
+/// Layout (offsets verified by seqlock protocol):
+///   0x000: seq (AtomicU64) ΓÇö even = consistent, odd = updating (time fields)
+///   0x008: monotonic_sec (AtomicU64)
+///   0x010: monotonic_nsec (AtomicU32) + padding
+///   0x018: realtime_sec (AtomicU64)
+///   0x020: realtime_nsec (AtomicU32) + padding
+///   0x028: tsc_freq_hz (AtomicU64)
+///   0x030: tsc_mult (u32) + tsc_shift (u32)
+///   0x038: tsc_base (AtomicU64)
+///   0x040: tsc_base_origin (AtomicU64) ΓÇö original TSC base at boot (preserved across syncs)
+///   0x048: pid_cpu_seq (AtomicU64) ΓÇö even = consistent, odd = updating (PID/CPU fields)
+///   0x050: pid (AtomicU64)
+///   0x058: cpu_id (AtomicU32) + padding
+///   0x060: thread_cputime_ns (AtomicU64) ΓÇö thread CPU time for CLOCK_SKYIOUS_THREAD_CPUTIME (100)
+///   0x068: kernel_flags (AtomicU64) ΓÇö kernel feature flags for CLOCK_SKYIOUS_KERNEL_FLAGS (103)
+///   0x070: process_cgroup_id (AtomicU64) ΓÇö cgroup ID for CLOCK_SKYIOUS_PROCESS_INFO (104)
+///   0x078: process_namespace_flags (AtomicU64) ΓÇö namespace flags for CLOCK_SKYIOUS_PROCESS_INFO (104)
+///   0x080: process_cap_effective (AtomicU64) ΓÇö effective capabilities for CLOCK_SKYIOUS_PROCESS_INFO (104)
