+        let Some(frame) = frame_allocator.allocate_frame() else {
+            crate::serial_write("vDSO: failed to allocate frame\n");
+            x86_64::instructions::interrupts::disable();
+            loop {
+                x86_64::instructions::hlt();
+            }
