+            let ptr = VDSO_PAGE_INFOS[cpu_id].as_mut_ptr();
+            VDSO_PAGES[cpu_id].store(ptr, Ordering::Release);
+            // Retain permanent kernel reference to frame to prevent reclamation
+            VDSO_FRAME_REFS[cpu_id] = Some(frame);
+        }
