+    CACHED_RTC_SEC.store(sec as u64, Ordering::Release);
+    CACHED_RTC_NSEC.store(nsec as u32 as u64, Ordering::Release);
+    CACHED_RTC_TSC.store(sampled_tsc, Ordering::Release);
